    def perform_commissioning(self, **kwargs):
        """This keyword is used to perform commissioning on a bts.
        | *Arguments* | *Default* | *Comments* | *Config Ref* |
        | dut | bts |  Section Name in Testline Config  | `testline_config` |
        | scf_file | scf_file given with pybot | or given filename will be looked in |  |
        |  |  | fw_user_path/config/<bts_id>/scfc_files |  |
        | skip_parameter_relation_errors | True | Skip parameter relation errors |  |
        | verify_bts_status | True | Verifies BTS status after commissioning |  |
        | wait_for_onair_status | 900 | Time to wait for while verifying BTS status |  |
        | timeout | 300 seconds | Timeout for commissioning operation |  |
        | alias | 'default' | Name of the execution context |  |
        | rat | optional | At least one of the RATs is Mandatory if rat check is required. | `testline_config` |

        *Usage :*

            _Perform Commissioning |	<source>    |   <alsia>_

        *Examples:*

        *Commission BTS with default arguments *
        | Perform Commissioning |
        *Commission BTS with explicit passed arguments *
        | Perform Commissioning | scf_file=/home/ute/scf1.xml | verify_bts_status=False | alias=conn1 |
        """
        return Commissioning().perform_commissioning(**kwargs)

    def perform_recommissioning(self, **kwargs):
        """This keyword is used to perform recommissioning on a bts.

        | *Arguments* | *Default* | *Comments* | *Config Ref* |
        | type | Mandatory | Type of recommissioning. Can be delta or param or ncf |  |
        | alias | default | Name of the execution context |  |
        | dut | bts |  Section Name in Testline Config  | `testline_config` |

        * Arguments for type delta *
        | *Arguments* | *Default* | *Comments* |
        | delta_file | Mandatory when 'type' is 'delta' | The path of the delta xml file to be used |
        | should_activate | True | should automatically activate plan |
        | skip_parameter_relation_errors | True | Skip parameter relation errors |
        | timeout | 120 | Timeout in seconds. Time to wait for positive procedure result |

        * Arguments for type param *
        | *Arguments* | *Default* | *Comments* |
        | operation | Mandatory | create, update or delete |
        | rat | common | The RAT the param belongs to |
        | param_path | Mandatory | Part of the distname or full distname |
        | value | Mandatory | The value to be applied |
        | skip_parameter_relation_errors | True | Skip parameter relation errors |
        | timeout | 120 | timeout in seconds |
        | ncf | False |  |

        * Arguments for type ncf *
        | *Arguments* | *Default* | *Comments* |
        | scf_file | Mandatory | Filepath to NCF file (string) |
        | verify_bts_status | False | Verifies bts is on air or not |
        | wait_for_onair_status | 900 | time to wait(seconds) before checking for status |
        | timeout | 300 | timeout in seconds |

        *Examples:*

        *Perform Delta type Recommissioning*
        | Perform Recommissioning | type=delta   |  delta_file=sample1.xml | skip_parameter_relation_errors=${True} | timeout=300 |
        *Perform Parameter type Recommissioning*
        | Perform Recommissioning | type=param   |  rat=lte  | param_path=MPLANENW-1:mPlaneDscp | operation=update  |  value=36 | timeout=300 |
        *Perform ncf type Recommissioning*
        | Perform Recommissioning | type=ncf | verify_bts_status= True | wait_for_on_air_status=1000 | timeout=300 |

        """
        return Commissioning().perform_recommissioning(**kwargs)

