    def verify_alarm(self, **kwargs):
        """
        _*Verify Alarm*_  This keyword is used to verify alarm.

        *Usage*:
        Verify Alarm     <faultid>    <rat>    <alarm_type>    <severity>    <should_exist>    <occurrences>
        <expected_alarms>    <check_unexpected_alarms>    <prev_alarms>    <timeout>    <alias>

        *Parameters:*
        | *Arguments* | *Comments* | *Default* | *Config Ref* |
        | dut | bts |  Section Name in Testline Config  | `testline_config` |
        | faultid | None | The fault id of the alarm |  |
        | rat | common | The RAT the alarm belongs to |  |
        | alarm_type | active | can be active or history |  |
        | severity | None | If None,  all severities are considered. Can be critical, major, |  |
        |  |  | minor or warning |  |
        | should_exist | True | ${True} if alarm should exist, ${False} if alarm should not exist (bool) |  |
        | occurrences | 1 | Expected occurrences of the alarm |  |
        | expected_alarms | None | List of alarms that can be expected. |  |
        | check_unexpected_alarms | True | Boolean to validate unexpected alarms or not |  |
        | prev_alarms | None | Previously returned Alarms list of dict for validating against the |  |
        |  |  | current alarms |  |
        | timeout | 300 | Timeout value |  |
        | alias | default | Name of the execution context |  |

        NOTE: One of the arguments faultid or expected_alarms is Mandatory.

         *Returns:*
        list : Alarm object list

        *Raises:*
        UnexpectedAlarmsFoundException if length of unexpected alarams is greater than 0.
        AlarmShouldNotExistException if alarm which should not exists is found.
        AlarmNotFoundException if requested alarm occurence is 0.
        AlarmNotFoundInRise if requested alarm not found in 'rise.csv'.
        AlarmRiseValidationFailed if alarm rise validation status is failed.
        AllAlarmOccurencesNotFoundException if all requested alarm occurence not found.

        *Examples:*
        | *keyword* |*faultid*|*rat*| *alarm_type* | *severity* | *should_exist* | *occurrences* | *expected_alarms* |
        |  |  |  |  |  |  |  |  | *check_unexpected_alarms* | *prev_alarms* | *timeout* | *alias* |
        | Verify Alarm | faultid=4003 | rat=lte | alarm_type=history | severity=major | should_exist=${False} |
        |  |  |  |  |  |  | occurrences=1 |  | check_unexpected_alarms=False | prev_alarms=None |
        |  |  |  |  |  |  |  |  |  |  | timeout=300 | alias=default |

        """
        return Alarms().verify_alarm(**kwargs)

    def get_alarms_summary(self, **kwargs):
        """
        _*Get Alarms Summary*_  This keyword is used to get summary of active alarms.

        *Usage*:
        Get Alarms Summary    <alarm_type>    <use_m2m>    <timeout>    <rat>    <alias>

        *Parameters:*
        | *Arguments* | *Comments* | *Default* | *Config Ref*  |
        | dut | bts |  Section Name in Testline Config  | `testline_config` |
        | alarm_type | active | str - active or historical alarms |  |
        | use_m2m | True | bool - (optional applicable only for release cuoam_21b or newer) m2m feature  |  |
        |  |  | activation flag. If set to False, internal API will be used instead of licensed API (M2M). |  |
        |  |  | Applicable for active alarms only. |  |
        | timeout | 300 | int - Timeout value |  |
        | rat | common | str- The RAT the alarm belongs to |  |
        | alias | default | str - Name of the execution context |  |

         *Returns:*
        dict : with the value of total amount of alarms and their severities and their number of occurrences.

        *Raises:*
        UnexpectedAlarmsFoundException if length of unexpected alarams is greater than 0.

        *Examples:*
        | Get Alarms Summary | alarm_type=active | rat=lte | alias=default |
        """
        return Alarms().get_active_alarms_summary(**kwargs)

