    def certificate_configure(self, **kwargs):
        """ This keyword is used to configure or get certificate details.
            Multiple operations are supported in same keyword.

        *Supported operations*
        | *Operation* | *Description* |
        | set_certificate_automatic_managment | Set certificate automatic managment. |
        | cmp_update_key | CMP update key. |
        | install_cmp_certificate | Install CMP certificate. |
        | install_certificate | Install certificate. |
        | get_certificate_list | Get certificate list. |
        | get_certificate_details | Get certificate details. |
        | restore_vendor_certificate | Delete all operator certificates |
        | delete_cert | Delete certificate. |

        | *Arguments* | *Default* | *Comments* | *Config Ref*  |
        | operation | Mandatory  | Operation from the above list |  |
        | dut | bts |  Section Name in Testline Config  | `testline_config` |
        | timeout | 60 seconds | Timeout for the operation |  |
        | alias | 'default' | Name of the execution context |  |
        | rat | optional | At least one of the RATs is Mandatory if rat check is required. | `testline_config` |

        * Arguments for set_certificate_automatic_managment *
        | *Arguments* | *Default* | *Comments* |
        | reference_number | Mandatory |  |
        | preshared_key | Mandatory |  |

       * Arguments for install_certificate *
        | *Arguments* | *Default* | *Comments* |
        | cert_file | Mandatory | The certificate file to be installed |
        | cert_type | Mandatory | Can be EE or CA |

       * Arguments for get_certificate_details *
        | *Arguments* | *Default* | *Comments* |
        | certificate_id | Mandatory | Resource id |

       * Arguments for delete_cert *
        | *Arguments* | *Default* | *Comments* |
        | Subject | Subject | |
        | all_certs | False | if True deletes all certificates |

        *Examples:*

        *Get Certificate Details *
        | Certificate Configure | operation=set_certificate_automatic_managment | reference_number=***** |
        preshared_key=***** |

        * BTSSM *
        Implementation Not available
        """
        return Certificate().certificate_configure(**kwargs)

    def test_ipconnectivity(self, **kwargs):
        """
        _*Test Ipconnectivity*_  Test IP Connectivity.

        *Usage*:
        Test Ipconnectivity     <destination_ip>    <payload_size>    <dscp>    <source_interface_name>
            <source_ip>   <alias>

        *Parameters:*
        | *Arguments* | *Default* | *Comments* | *Config Ref* |
        | destination_ip | Mandatory | IP whose connectivity is to be tested as string. |  |
        | payload_size | Mandatory | size of payload as int. |  |
        | dscp | Mandatory | values of IPv4 and IPv6 headers to classify data packets and manage |  |
        |  |  | network traffic as int. |  |
        | dut | bts |  Section Name in Testline Config  | `testline_config` |
        | source_interface_name | default | Name of the external interface selected as source provided as string. | |
        | source_ip | None | IPv4/IPv6 address of the external interface selected as source as string. | |
        | alias | default | Name of execution context. | |
        | rat | common | At least one of the RATs is Mandatory eg. lte/wcdma/gsm etc. | |

        *Returns:*
        It returns IP connectivity test result dict

        *Raises:*
        ApiException

        *Example*
        | *keyword* | *destination_ip* | *payload_size* | *dscp* | *source_interface_name* | *source_ip* |
            *alias* |
        | Test Ipconnectivity | destination_ip='10.10.10.10' | payload-size=10 | dscp=3 |
        |   |   |   |   | source_interface_name = default | source_ip = '20.20.20.20' | alias=default |
        """

        return OtherCuOps().test_ipconnectivity(**kwargs)

