    def pmtu_discovery(self, **kwargs):
        """
        _*Pmtu Discovery*_ Pmtu discovery

        *Usage*:
        Pmtu Discovery     <name>    <source_ip>    <destination_ip>    <dscp>    <timeout>
                <alias>

        *Parameters:*
        | *Arguments* | *Default* | *Comments* | *Config Ref* |
        | name | Mandatory |  name of the external interface selected as source  |  |
        | | |  like: OAMAGENT_po-cran5-oamext-0_oam_certman-server |  |
        | source_ip | Mandatory | IPv4/IPv6 address of the external interface selected as source |  |
        | destination_ip | Mandatory |  IPv4/IPv6 address of the external interface selected as destination |  |
        | dscp | Mandatory |values of IPv4 and IPv6 headers to classify data packets  |  |
        |  |  | and manage network traffic |  |
        | timeout | Optional | Timeout for the operation, defaults to 30 | |
        | alias | default | VduConnection object or string name alias if used | |

        *Returns:*
        A dict including status, result, reason for result of pmtu discovery

        *Example*
        | *keyword* | *name* | *source_ip* | *destination_ip* | *dscp* | *timeout* | *alias* |
        | Pmtu Discovery | name=OAMAGENT_po-cran5-oamext-0_oam_certman-server | source_ip='' | destination_ip='' |
        |   |   |   |   | dscp = 3 | timeout = 30 | alias=default |
        """

        return OtherCuOps().pmtu_discovery(**kwargs)

